    await expect(pg_uma.getByTestId("header-due-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("my-due-total")).toHaveText("");
    await expect(pg_uma.getByTestId("my-overdue-total")).toHaveText("");
    await expect(pg_uma.getByTestId("my-crew-due-total")).toHaveText("");
    expect(await ui.addClaim(pg_uma, p_ben, {"amount": "0.40", "date": "2026-03-28"})).toBeNull();
    expect(await ui.editInline(pg_uma, c_ben_0, "7.77")).toBe(true);
    await ui.sortBy(pg_uma, "due-total");
    expect(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33", "date": "2026-04-02", "note": "n", "tags": "b,a,a"})).toBeNull();
    expect(await ui.addClaim(pg_uma, p_ben, {"amount": "10.35", "date": "2026-03-01"})).toBeNull();
    expect(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33", "date": "2026-03-15", "tags": " c "})).toBeNull();
