    /** The person's own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** The person's dated terms: each in force from its from-date until the next one's, ahead of the undated. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_terms", joinColumns = @JoinColumn(name = "person_id"))
    private List<TermsFrom> datedTerms = new ArrayList<>();

    /** The person's contact, trimmed and lower-cased; null when they have none. */
    @Column(name = "contact")
    private String contact;

    /** The person's tags: trimmed, lower-cased, without repeats, sorted and joined by commas; none when they have
     *  none. */
    @Column(name = "tags", length = 1000)
    private String tags;

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** The retirements the person was unretired from: a claim dated within one is refused. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_past_retirement", joinColumns = @JoinColumn(name = "person_id"))
    private List<PastRetirement> pastRetirements = new ArrayList<>();

    /** The person's holds: their open claims dated within one, and not bound by a statement, count in no live
     *  total. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
    private List<Hold> holds = new ArrayList<>();

    /** The other names the person is found by, stored trimmed. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "alias", nullable = false)
    private Set<String> aliases = new HashSet<>();

    /** Raised on every save; an edit made from an older version is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new GradeFrom(null, grade));
    }

    /** A copy of the person on another sheet, unsaved: their name, place in the list, grades, terms, contact, tags,
     *  aliases, holds and retirements (current and past); not where they came from. */
    public Person copyTo(String sheetId) {
        Person copy = new Person();
        copy.sheetId = sheetId;
        copy.name = name;
        copy.position = position;
        grades.forEach(g -> copy.grades.add(new GradeFrom(g.getFromDate(), g.getGrade())));
        copy.terms = terms;
        datedTerms.forEach(t -> copy.datedTerms.add(new TermsFrom(t.getFromDate(), t.getTerms())));
        copy.contact = contact;
        copy.tags = tags;
        copy.retiredFrom = retiredFrom;
        pastRetirements.forEach(r -> copy.pastRetirements.add(new PastRetirement(r.getFromDate(), r.getToDate())));
        holds.forEach(h -> copy.holds.add(new Hold(h.getFromDate(), h.getToDate())));
        copy.aliases.addAll(aliases);
        return copy;
    }

    public Long getId() {
        return id;
    }

    /** Give an unsaved person rebuilt from the sheet's history the id it had then, so its figures are worked out as
     *  the live one's are; it is never saved. */
    public void rebuiltWithId(long id) {
        this.id = id;
    }

    public String getSheetId() {
        return sheetId;
    }
